  function getCategories(type) {
    var presets = type === 'physical' ? PHYSICAL_DATA.presets : type === 'fm' ? FM_DATA.presets : type === 'additive' ? ADDITIVE_DATA.presets : type === 'granular' ? GRANULAR_DATA.presets : type === 'vocoderSynth' ? VOCODER_DATA.presets : type === 'wavefolder' ? WAVEFOLDER_DATA.presets : type === 'formant' ? FORMANT_DATA.presets : type === 'modal' ? MODAL_DATA.presets : type === 'ringmod' ? RINGMOD_DATA.presets : type === 'chord' ? CHORD_DATA.presets : type === 'superwave' ? SUPERWAVE_DATA.presets : type === 'wavetable' ? WAVETABLE_SYNTH_DATA.presets : type === 'phasedist' ? PHASEDIST_DATA.presets : type === 'chip' ? CHIP_DATA.presets : type === 'bytebeat' ? BYTEBEAT_DATA.presets : type === 'vector' ? VECTOR_DATA.presets : type === 'drumsyn' ? DRUMSYN_DATA.presets : type === 'pulsar' ? PULSAR_DATA.presets : type === 'reed' ? REED_DATA.presets : SUBTRACTIVE_DATA.presets;
    var seen = {};
    var cats = [];
    for (var i = 0; i < presets.length; i++) {
      var cat = presets[i].category;
      if (!seen[cat]) {
        seen[cat] = true;
        cats.push(cat);
      }
    }
    return cats;
  }

  function getPresetsByCategory(type, category) {
    var presets = type === 'physical' ? PHYSICAL_DATA.presets : type === 'fm' ? FM_DATA.presets : type === 'additive' ? ADDITIVE_DATA.presets : type === 'granular' ? GRANULAR_DATA.presets : type === 'vocoderSynth' ? VOCODER_DATA.presets : type === 'wavefolder' ? WAVEFOLDER_DATA.presets : type === 'formant' ? FORMANT_DATA.presets : type === 'modal' ? MODAL_DATA.presets : type === 'ringmod' ? RINGMOD_DATA.presets : type === 'chord' ? CHORD_DATA.presets : type === 'superwave' ? SUPERWAVE_DATA.presets : type === 'wavetable' ? WAVETABLE_SYNTH_DATA.presets : type === 'phasedist' ? PHASEDIST_DATA.presets : type === 'chip' ? CHIP_DATA.presets : type === 'bytebeat' ? BYTEBEAT_DATA.presets : type === 'vector' ? VECTOR_DATA.presets : type === 'drumsyn' ? DRUMSYN_DATA.presets : type === 'pulsar' ? PULSAR_DATA.presets : type === 'reed' ? REED_DATA.presets : SUBTRACTIVE_DATA.presets;
    var result = [];
    for (var i = 0; i < presets.length; i++) {
      if (presets[i].category === category) {
        result.push(presets[i]);
      }
    }
    return result;
  }

  /**
   * Apply a subtractive preset to an instrument.
   * Deep-copies preset settings into the instrument's settings object,
   * then updates the UI via loadInstrumentSettings.
   * @param {Object} preset - Preset object from SUBTRACTIVE_DATA
   * @param {number} instIndex - Instrument index (0-3)
   */
  function applySubtractivePreset(preset, instIndex) {
    if (typeof instIndex !== 'number') instIndex = SL.audio.getCurrentInstrument();
    var settings = SL.audio.getSettingsForInstrument(instIndex);
    if (!settings || !preset || !preset.settings) return;

    var src = preset.settings;

    // Copy oscillators
    if (src.osc) {
      for (var i = 0; i < src.osc.length && i < settings.osc.length; i++) {
        var o = src.osc[i];
        settings.osc[i] = {
          wave: o.wave || 'sine',
          oct: o.oct || 0,
          detune: o.detune || 0,
          level: o.level != null ? o.level : 80,
          pulseWidth: o.pulseWidth != null ? o.pulseWidth : 50,
          superSawSpread: o.superSawSpread != null ? o.superSawSpread : 50
        };
      }
    }

    // Copy ADSR (A/D/R clamped to ADSR_MAX_MS — UI slider max is also 1 s).
    // Sustain (S) is a level, not a time, so it's not clamped.
    var ADSR_MAX_MS = 1000;
    if (src.adsr) {
      var srcA = src.adsr.a != null ? src.adsr.a : 10;
      var srcD = src.adsr.d != null ? src.adsr.d : 100;
      var srcR = src.adsr.r != null ? src.adsr.r : 200;
      settings.adsr = {
        a: srcA > ADSR_MAX_MS ? ADSR_MAX_MS : srcA,
        d: srcD > ADSR_MAX_MS ? ADSR_MAX_MS : srcD,
        s: src.adsr.s != null ? src.adsr.s : 70,
        r: srcR > ADSR_MAX_MS ? ADSR_MAX_MS : srcR
      };
    }

    // Copy filter
    if (src.filter) {
      settings.filter = {
        enabled: src.filter.enabled !== false,
        type: src.filter.type || 'lowpass',
        freq: src.filter.freq != null ? src.filter.freq : 850,
        q: src.filter.q != null ? src.filter.q : 10,
        keyTrack: src.filter.keyTrack != null ? src.filter.keyTrack : 0,
        model: src.filter.model || 'butterworth',
        slope: src.filter.slope || 24
      };
    }

    // Copy filter envelope (A/D/R clamped to ADSR_MAX_MS).
    if (src.filterEnv) {
      var feA = src.filterEnv.a != null ? src.filterEnv.a : 200;
      var feD = src.filterEnv.d != null ? src.filterEnv.d : 600;
      var feR = src.filterEnv.r != null ? src.filterEnv.r : 775;
      settings.filterEnv = {
        enabled: !!src.filterEnv.enabled,
        amount: src.filterEnv.amount != null ? src.filterEnv.amount : 24,
        a: feA > ADSR_MAX_MS ? ADSR_MAX_MS : feA,
        d: feD > ADSR_MAX_MS ? ADSR_MAX_MS : feD,
        s: src.filterEnv.s != null ? src.filterEnv.s : 0,
        r: feR > ADSR_MAX_MS ? ADSR_MAX_MS : feR,
        link: !!src.filterEnv.link
      };
    }

    // Copy noise
    if (src.noise) {
      settings.noise = {
        type: src.noise.type || 'white',
        level: src.noise.level != null ? src.noise.level : 0
      };
    }

    // Ensure instrument type is subtractive
    SL.audio.setInstrumentType(instIndex, 'subtractive');

    // Only update shared UI and refresh active audio for the current instrument.
    // Loading non-current instrument settings to DOM pollutes the shared UI elements,
    // causing saveInstrumentSettings to corrupt other instruments' settings on next read.
    if (instIndex === SL.audio.getCurrentInstrument()) {
      SL.audio.loadInstrumentSettings(instIndex);

      if (typeof SL.audio.refreshActiveOscillators === 'function') {
        SL.audio.refreshActiveOscillators();
      }
      if (typeof SL.audio.refreshFilter === 'function') {
        SL.audio.refreshFilter();
      }
      if (typeof SL.audio.updateWorkletFilter === 'function') {
        SL.audio.updateWorkletFilter(instIndex);
      }
      if (typeof SL.audio.restartContinuousNoise === 'function') {
        SL.audio.restartContinuousNoise();
      }
    }

  }

  /**
   * Apply an FM preset to an instrument.
   * Uses SL.audio.setFMSettings to update the FM engine parameters.
   * @param {Object} preset - Preset object from FM_DATA
   * @param {number} instIndex - Instrument index (0-3)
   */
  function applyFMPreset(preset, instIndex) {
    if (typeof instIndex !== 'number') instIndex = SL.audio.getCurrentInstrument();
    if (!preset || !preset.settings) return;

    var src = preset.settings;
    var fmSettings = {
      algorithm: src.algorithm || 1,
      feedback: src.feedback || 0,
      operators: []
    };

    if (src.operators) {
      for (var i = 0; i < src.operators.length; i++) {
        var op = src.operators[i];
        fmSettings.operators.push({
          ratioCoarse: op.ratioCoarse != null ? op.ratioCoarse : 1,
          ratioFine: op.ratioFine != null ? op.ratioFine : 0,
          level: op.level != null ? op.level : 0,
          detune: op.detune != null ? op.detune : 7,
          velocitySens: op.velocitySens != null ? op.velocitySens : 0,
          rateScaling: op.rateScaling != null ? op.rateScaling : 0,
          envelope: op.envelope ? {
            R1: op.envelope.R1 != null ? op.envelope.R1 : 95,
            R2: op.envelope.R2 != null ? op.envelope.R2 : 50,
            R3: op.envelope.R3 != null ? op.envelope.R3 : 50,
            R4: op.envelope.R4 != null ? op.envelope.R4 : 50,
            L1: op.envelope.L1 != null ? op.envelope.L1 : 99,
            L2: op.envelope.L2 != null ? op.envelope.L2 : 99,
            L3: op.envelope.L3 != null ? op.envelope.L3 : 99,
            L4: op.envelope.L4 != null ? op.envelope.L4 : 0
          } : { R1: 95, R2: 50, R3: 50, R4: 50, L1: 99, L2: 99, L3: 99, L4: 0 }
        });
      }
    }

    // Set instrument type to FM
    SL.audio.setInstrumentType(instIndex, 'fm');

    // Apply FM settings to audio-engine state (for UI/save)
    SL.audio.setFMSettings(instIndex, fmSettings);

    // Sync settings to FM engine (where noteOn actually reads from)
    if (SL.fm && SL.fm.setSettings) {
      SL.fm.setSettings(instIndex, fmSettings);
    }

    // Load UI if this is the current instrument
    if (instIndex === SL.audio.getCurrentInstrument()) {
      SL.audio.loadInstrumentSettings(instIndex);
    }

  }

