  // Reset filter to clean state when switching engines.
  // Prevents the previous preset's filter (e.g. Rhodes LP 650Hz) from
  // persisting and muffling a preset that has no filter settings.
  var CLEAN_FILTER = {
    enabled: false,
    type: 'lowpass',
    freq: 4000,
    q: 1,
    keyTrack: 0,
    model: 'butterworth',
    slope: 24
  };

  function _resetFilterForEngine(instIndex) {
    var instruments = SL.audio.getInstruments();
    if (instruments && instruments[instIndex] && instruments[instIndex].settings) {
      instruments[instIndex].settings.filter = JSON.parse(JSON.stringify(CLEAN_FILTER));
    }
  }

  function applyPhysicalPreset(preset, instIndex) {
    if (instIndex === undefined) instIndex = SL.audio.getCurrentInstrument();
    if (!preset || !preset.settings) return;

    var physSettings = JSON.parse(JSON.stringify(preset.settings));

    // Set instrument type to physical
    SL.audio.setInstrumentType(instIndex, 'physical');

    // Apply physical settings to audio-engine state
    SL.audio.setPhysicalSettings(instIndex, physSettings);

    // Sync settings to physical engine
    if (SL.physical && SL.physical.setSettings) {
      SL.physical.setSettings(instIndex, physSettings);
    }

    // Load UI if this is the current instrument
    if (instIndex === SL.audio.getCurrentInstrument()) {
      SL.audio.loadInstrumentSettings(instIndex);
    }

  }


